style.css:
@-moz-document domain("roblox.com") {
/* Changes the main background to a Creeper theme */
  body, .dark-theme, .light-theme {
    background-image: url('https://images.unsplash.com/photo-1627856013091-fed6e4e300cd') !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
  }

  /* Makes page containers slightly transparent so you can see the background */
  .content, .container-main, .section-content {
    background-color: rgba(0, 0, 0, 0.75) !important;
  }
}
